package io.github.diodeme.ji.session.tree;

import io.github.diodeme.ji.ai.Message;
import io.github.diodeme.ji.ai.ModelRef;
import io.github.diodeme.ji.ai.Usage;
import io.github.diodeme.ji.session.SessionSnapshot;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;

/** Immutable Pi-compatible Session mutation log plus the execution projection consumed by Agent Core. */
public record SessionDocument(
        int schemaVersion,
        Metadata metadata,
        long revision,
        long nextSequence,
        List<Mutation> log,
        ModelRef model,
        String workingDirectory,
        Usage usage,
        Optional<SessionSnapshot.ActiveRun> activeRun,
        List<CompactionCheckpoint> compactions) {
    public static final int CURRENT_SCHEMA_VERSION = 1;

    public SessionDocument {
        if (schemaVersion != CURRENT_SCHEMA_VERSION) {
            throw new IllegalArgumentException("unsupported Session document schema: " + schemaVersion);
        }
        Objects.requireNonNull(metadata, "metadata");
        if (revision < 0 || nextSequence < 1) {
            throw new IllegalArgumentException("Session revisions and sequences are out of range");
        }
        log = List.copyOf(log);
        Objects.requireNonNull(model, "model");
        requireText(workingDirectory, "workingDirectory");
        Objects.requireNonNull(usage, "usage");
        activeRun = activeRun == null ? Optional.empty() : activeRun;
        compactions = List.copyOf(compactions);
        replay(log, nextSequence);
        validateCompactions(compactions);
    }

    public static SessionDocument empty(String sessionId, ModelRef model, String workingDirectory, Instant createdAt) {
        return new SessionDocument(CURRENT_SCHEMA_VERSION,
                new Metadata(sessionId, createdAt, Optional.empty()), 0, 1, List.of(), model,
                workingDirectory, Usage.ZERO, Optional.empty(), List.of());
    }

    public SessionSnapshot snapshot() {
        List<Message> transcript = entries().stream()
                .filter(entry -> entry.kind() == EntryKind.MESSAGE)
                .map(Entry::message)
                .flatMap(Optional::stream)
                .toList();
        return new SessionSnapshot(metadata.sessionId(), revision, model, workingDirectory, transcript, usage, activeRun);
    }

    public List<Entry> entries() {
        return replay(log, nextSequence).entries();
    }

    public List<Record> records() {
        return replay(log, nextSequence).records();
    }

    public List<Lane> lanes() {
        return replay(log, nextSequence).lanes();
    }

    public Map<String, String> labels() {
        return replay(log, nextSequence).labels();
    }

    public Optional<String> name() {
        return replay(log, nextSequence).name();
    }

    public Optional<Entry> entry(String entryId) {
        return entries().stream().filter(entry -> entry.id().equals(entryId)).findFirst();
    }

    public List<Entry> branch(String laneName) {
        Projection state = replay(log, nextSequence);
        String leaf = state.lanes().stream().filter(lane -> lane.name().equals(laneName)).findFirst()
                .orElseThrow(() -> new IllegalArgumentException("lane not found: " + laneName))
                .leafEntryId().orElse(null);
        Map<String, Entry> byId = new HashMap<>();
        state.entries().forEach(entry -> byId.put(entry.id(), entry));
        var reversed = new ArrayList<Entry>();
        var visited = new HashSet<String>();
        while (leaf != null) {
            if (!visited.add(leaf)) throw new IllegalStateException("Session branch contains a cycle at " + leaf);
            Entry current = byId.get(leaf);
            if (current == null) throw new IllegalStateException("Session branch references missing entry " + leaf);
            reversed.add(current);
            leaf = current.parentId().orElse(null);
        }
        return reversed.reversed();
    }

    public SessionDocument appendEntry(String lane, String id, EntryKind kind, Optional<Message> message,
                                       Map<String, Object> data, Instant createdAt) {
        Projection state = replay(log, nextSequence);
        Lane pointer = state.lanes().stream().filter(candidate -> candidate.name().equals(lane)).findFirst()
                .orElseThrow(() -> new IllegalArgumentException("lane not found: " + lane));
        Entry entry = new Entry(id, pointer.leafEntryId(), createdAt, kind, message, data);
        return appendMutation(new EntryMutation(nextSequence, Optional.of(lane), entry));
    }

    public SessionDocument appendRecord(String id, String lane, RecordKind kind,
                                        Optional<String> operationId, Optional<OperationKind> operationKind,
                                        Optional<OperationOutcome> outcome, Map<String, Object> data, Instant createdAt) {
        return appendMutation(new RecordMutation(nextSequence,
                new Record(id, lane, kind, operationId, operationKind, outcome, data, createdAt)));
    }

    public SessionDocument createLane(String lane, Optional<String> atEntryId) {
        return appendMutation(new LaneMutation(nextSequence, LaneMutationKind.CREATE, lane, atEntryId));
    }

    public SessionDocument moveLane(String lane, Optional<String> toEntryId) {
        return appendMutation(new LaneMutation(nextSequence, LaneMutationKind.MOVE, lane, toEntryId));
    }

    public SessionDocument setName(Optional<String> nextName) {
        return appendMutation(new NameFactMutation(nextSequence, nextName));
    }

    public SessionDocument setLabel(String entryId, Optional<String> label) {
        return appendMutation(new LabelFactMutation(nextSequence, entryId, label));
    }

    public SessionDocument fork(String sessionId, String laneName, Optional<String> targetEntryId,
                                ForkPosition position, Instant createdAt) {
        requireText(sessionId, "sessionId");
        Objects.requireNonNull(targetEntryId, "targetEntryId");
        Objects.requireNonNull(position, "position");
        List<Entry> sourceBranch = branch(laneName);
        String selected = targetEntryId.orElseGet(() -> sourceBranch.isEmpty() ? null : sourceBranch.getLast().id());
        List<Entry> copied;
        if (selected == null) {
            copied = List.of();
        } else {
            Entry target = entry(selected).orElseThrow(() -> new IllegalArgumentException("fork target not found: " + selected));
            if (target.kind() != EntryKind.MESSAGE) throw new IllegalArgumentException("fork target must be a message entry");
            if (sourceBranch.stream().noneMatch(candidate -> candidate.id().equals(selected))) {
                throw new IllegalArgumentException("fork target is not on the selected lane");
            }
            String lastIncluded = position == ForkPosition.AT ? target.id() : target.parentId().orElse(null);
            var mutable = new ArrayList<Entry>();
            for (Entry entry : sourceBranch) {
                if (lastIncluded == null) break;
                mutable.add(entry);
                if (entry.id().equals(lastIncluded)) break;
            }
            copied = List.copyOf(mutable);
        }
        long sequence = 1;
        var forkLog = new ArrayList<Mutation>();
        for (Entry entry : copied) {
            forkLog.add(new EntryMutation(sequence++, Optional.of("main"), entry));
        }
        if (name().isPresent()) forkLog.add(new NameFactMutation(sequence++, name()));
        Map<String, String> labels = labels();
        for (Entry entry : copied) {
            String label = labels.get(entry.id());
            if (label != null) forkLog.add(new LabelFactMutation(sequence++, entry.id(), Optional.of(label)));
        }
        return new SessionDocument(CURRENT_SCHEMA_VERSION,
                new Metadata(sessionId, createdAt, Optional.of(metadata.sessionId())), 0, sequence,
                forkLog, model, workingDirectory, Usage.ZERO, Optional.empty(), List.of());
    }

    private SessionDocument appendMutation(Mutation mutation) {
        var nextLog = new ArrayList<>(log);
        nextLog.add(mutation);
        return new SessionDocument(schemaVersion, metadata, Math.incrementExact(revision),
                Math.incrementExact(nextSequence), nextLog, model, workingDirectory, usage, activeRun, compactions);
    }

    public enum ForkPosition { BEFORE, AT }
    public enum EntryKind { MESSAGE, MODEL_CHANGE, THINKING_LEVEL_CHANGE, ACTIVE_TOOLS_CHANGE, COMPACTION, BRANCH_SUMMARY, CUSTOM }
    public enum RecordKind { OPERATION_STARTED, OPERATION_FINISHED, STEP_ATTEMPT, TOOL_STARTED, QUEUE_ENQUEUED, QUEUE_CANCELLED, USAGE }
    public enum OperationKind { RUN, COMPACTION, NAVIGATION }
    public enum OperationOutcome { COMPLETED, ABORTED, FAILED, DECLINED }
    public enum LaneMutationKind { CREATE, MOVE }
    public enum CompactionStatus { RUNNING, PAUSED, COMPLETED, FAILED, CANCELLED }

    public record Metadata(String sessionId, Instant createdAt, Optional<String> parentSessionId) {
        public Metadata {
            requireText(sessionId, "sessionId");
            Objects.requireNonNull(createdAt, "createdAt");
            parentSessionId = parentSessionId == null ? Optional.empty() : parentSessionId;
            parentSessionId.ifPresent(parent -> requireText(parent, "parentSessionId"));
        }
    }

    public sealed interface Mutation permits EntryMutation, RecordMutation, LaneMutation,
            NameFactMutation, LabelFactMutation {
        long sequence();
    }

    public record EntryMutation(long sequence, Optional<String> lane, Entry entry) implements Mutation {
        public EntryMutation {
            requireSequence(sequence);
            lane = lane == null ? Optional.empty() : lane;
            lane.ifPresent(value -> requireText(value, "lane"));
            Objects.requireNonNull(entry, "entry");
        }
    }

    public record RecordMutation(long sequence, Record record) implements Mutation {
        public RecordMutation {
            requireSequence(sequence);
            Objects.requireNonNull(record, "record");
        }
    }

    public record LaneMutation(long sequence, LaneMutationKind kind, String lane,
                               Optional<String> leafEntryId) implements Mutation {
        public LaneMutation {
            requireSequence(sequence);
            Objects.requireNonNull(kind, "kind");
            requireText(lane, "lane");
            leafEntryId = leafEntryId == null ? Optional.empty() : leafEntryId;
        }
    }

    public record NameFactMutation(long sequence, Optional<String> name) implements Mutation {
        public NameFactMutation {
            requireSequence(sequence);
            name = name == null ? Optional.empty() : name;
        }
    }

    public record LabelFactMutation(long sequence, String entryId, Optional<String> label) implements Mutation {
        public LabelFactMutation {
            requireSequence(sequence);
            requireText(entryId, "entryId");
            label = label == null ? Optional.empty() : label;
        }
    }

    public record Entry(String id, Optional<String> parentId, Instant createdAt,
                        EntryKind kind, Optional<Message> message, Map<String, Object> data) {
        public Entry {
            requireText(id, "entry id");
            parentId = parentId == null ? Optional.empty() : parentId;
            Objects.requireNonNull(createdAt, "createdAt");
            Objects.requireNonNull(kind, "kind");
            message = message == null ? Optional.empty() : message;
            data = immutableJsonObject(data);
            if ((kind == EntryKind.MESSAGE) != message.isPresent()) {
                throw new IllegalArgumentException("only message entries carry a Message");
            }
        }
    }

    public record Record(String id, String lane, RecordKind kind,
                         Optional<String> operationId, Optional<OperationKind> operationKind,
                         Optional<OperationOutcome> outcome, Map<String, Object> data, Instant createdAt) {
        public Record {
            requireText(id, "record id");
            requireText(lane, "lane");
            Objects.requireNonNull(kind, "kind");
            operationId = operationId == null ? Optional.empty() : operationId;
            operationKind = operationKind == null ? Optional.empty() : operationKind;
            outcome = outcome == null ? Optional.empty() : outcome;
            data = immutableJsonObject(data);
            Objects.requireNonNull(createdAt, "createdAt");
            if (kind == RecordKind.OPERATION_STARTED && (operationId.isEmpty() || operationKind.isEmpty())) {
                throw new IllegalArgumentException("operation start requires identity and kind");
            }
            if (kind == RecordKind.OPERATION_FINISHED && (operationId.isEmpty() || outcome.isEmpty())) {
                throw new IllegalArgumentException("operation finish requires identity and outcome");
            }
        }
    }

    public record Lane(String name, Optional<String> leafEntryId) {
        public Lane {
            requireText(name, "lane");
            leafEntryId = leafEntryId == null ? Optional.empty() : leafEntryId;
        }
    }

    public record CompactionCheckpoint(String compactionId, String lane, CompactionStatus status,
                                       long revision, int attempt, String resultEntryId,
                                       Optional<String> summary, List<Message> retainedTail,
                                       long tokensBefore, Usage usage) {
        public CompactionCheckpoint {
            requireText(compactionId, "compactionId");
            requireText(lane, "lane");
            Objects.requireNonNull(status, "status");
            if (revision < 0 || attempt < 1 || tokensBefore < 0) throw new IllegalArgumentException("compaction counters are invalid");
            requireText(resultEntryId, "resultEntryId");
            summary = summary == null ? Optional.empty() : summary;
            retainedTail = List.copyOf(retainedTail);
            Objects.requireNonNull(usage, "usage");
            if ((status == CompactionStatus.COMPLETED) != summary.isPresent()) {
                throw new IllegalArgumentException("only completed compaction has a summary");
            }
        }
    }

    private record Projection(List<Entry> entries, List<Record> records, List<Lane> lanes,
                              Map<String, String> labels, Optional<String> name) {}

    private static Projection replay(List<Mutation> mutations, long nextSequence) {
        var entries = new ArrayList<Entry>();
        var records = new ArrayList<Record>();
        var entriesById = new LinkedHashMap<String, Entry>();
        var usedIds = new HashSet<String>();
        var lanes = new LinkedHashMap<String, Optional<String>>();
        lanes.put("main", Optional.empty());
        var labels = new LinkedHashMap<String, String>();
        var openByLane = new HashMap<String, String>();
        Optional<String> name = Optional.empty();
        long expected = 1;
        for (Mutation mutation : mutations.stream().sorted(Comparator.comparingLong(Mutation::sequence)).toList()) {
            if (mutation.sequence() != expected++) throw new IllegalArgumentException("Session sequence must be contiguous");
            if (mutation instanceof EntryMutation append) {
                Entry entry = append.entry();
                if (!usedIds.add(entry.id())) throw new IllegalArgumentException("Session entry/record id is duplicated");
                entry.parentId().ifPresent(parent -> {
                    if (!entriesById.containsKey(parent)) throw new IllegalArgumentException("entry parent must be an earlier entry");
                });
                append.lane().ifPresent(lane -> {
                    Optional<String> leaf = lanes.get(lane);
                    if (leaf == null) throw new IllegalArgumentException("entry references missing lane");
                    if (!leaf.equals(entry.parentId())) throw new IllegalArgumentException("entry does not chain to lane leaf");
                    lanes.put(lane, Optional.of(entry.id()));
                });
                entries.add(entry);
                entriesById.put(entry.id(), entry);
            } else if (mutation instanceof RecordMutation append) {
                Record record = append.record();
                if (!lanes.containsKey(record.lane())) throw new IllegalArgumentException("record references missing lane");
                if (!usedIds.add(record.id())) throw new IllegalArgumentException("Session entry/record id is duplicated");
                if (record.kind() == RecordKind.OPERATION_STARTED
                        && openByLane.putIfAbsent(record.lane(), record.operationId().orElseThrow()) != null) {
                    throw new IllegalArgumentException("lane has more than one open operation");
                }
                if (record.kind() == RecordKind.OPERATION_FINISHED) {
                    openByLane.remove(record.lane(), record.operationId().orElseThrow());
                }
                records.add(record);
            } else if (mutation instanceof LaneMutation lane) {
                lane.leafEntryId().ifPresent(leaf -> {
                    if (!entriesById.containsKey(leaf)) throw new IllegalArgumentException("lane target is missing");
                });
                if (lane.kind() == LaneMutationKind.CREATE && lanes.putIfAbsent(lane.lane(), lane.leafEntryId()) != null) {
                    throw new IllegalArgumentException("lane already exists");
                }
                if (lane.kind() == LaneMutationKind.MOVE) {
                    if (!lanes.containsKey(lane.lane())) throw new IllegalArgumentException("lane not found");
                    lanes.put(lane.lane(), lane.leafEntryId());
                }
            } else if (mutation instanceof NameFactMutation fact) {
                name = fact.name();
            } else if (mutation instanceof LabelFactMutation fact) {
                if (!entriesById.containsKey(fact.entryId())) throw new IllegalArgumentException("label target is missing");
                if (fact.label().isPresent()) labels.put(fact.entryId(), fact.label().orElseThrow());
                else labels.remove(fact.entryId());
            }
        }
        if (expected != nextSequence) throw new IllegalArgumentException("nextSequence must follow the final mutation");
        List<Lane> pointers = lanes.entrySet().stream().map(entry -> new Lane(entry.getKey(), entry.getValue())).toList();
        return new Projection(List.copyOf(entries), List.copyOf(records), pointers, Map.copyOf(labels), name);
    }

    private static void validateCompactions(List<CompactionCheckpoint> compactions) {
        if (compactions.stream().filter(value -> value.status() == CompactionStatus.RUNNING || value.status() == CompactionStatus.PAUSED).count() > 1) {
            throw new IllegalArgumentException("Session may have only one unfinished compaction");
        }
        if (compactions.stream().map(CompactionCheckpoint::compactionId).distinct().count() != compactions.size()) {
            throw new IllegalArgumentException("compaction identities must be unique");
        }
    }

    private static Map<String, Object> immutableJsonObject(Map<String, Object> value) {
        Objects.requireNonNull(value, "data");
        return Map.copyOf(value);
    }

    private static void requireSequence(long sequence) {
        if (sequence < 1) throw new IllegalArgumentException("sequence must be positive");
    }

    private static void requireText(String value, String name) {
        if (value == null || value.isBlank()) throw new IllegalArgumentException(name + " must not be blank");
    }
}

