package io.github.diodeme.ji.session.tree;

import io.github.diodeme.ji.ai.Message;
import io.github.diodeme.ji.ai.ModelRef;
import io.github.diodeme.ji.ai.Usage;
import io.github.diodeme.ji.session.SessionSnapshot;
import io.github.diodeme.ji.session.model.CanonicalSessionState;
import io.github.diodeme.ji.session.model.Recovery;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;

/** Immutable Pi-compatible Session mutation log plus the execution projection consumed by Agent Core. */
public record SessionDocument(
        int schemaVersion,
        Metadata metadata,
        long revision,
        long nextSequence,
        List<Mutation> log,
        ModelRef model,
        String workingDirectory,
        Usage usage,
        CanonicalSessionState execution) {
    public static final int CURRENT_SCHEMA_VERSION = 1;

    public SessionDocument {
        if (schemaVersion != CURRENT_SCHEMA_VERSION) {
            throw new IllegalArgumentException("unsupported Session document schema: " + schemaVersion);
        }
        Objects.requireNonNull(metadata, "metadata");
        if (revision < 0 || nextSequence < 1) {
            throw new IllegalArgumentException("Session revisions and sequences are out of range");
        }
        log = List.copyOf(log);
        Objects.requireNonNull(model, "model");
        requireText(workingDirectory, "workingDirectory");
        Objects.requireNonNull(usage, "usage");
        Objects.requireNonNull(execution, "execution");
        if (!execution.sessionId().value().equals(metadata.sessionId())) {
            throw new IllegalArgumentException("execution state belongs to another Session");
        }
        if (execution.revision() != revision) {
            throw new IllegalArgumentException("document and execution revisions must match");
        }
        replay(log, nextSequence);
    }

    public static SessionDocument empty(String sessionId, ModelRef model, String workingDirectory, Instant createdAt) {
        var execution = new CanonicalSessionState(
                new CanonicalSessionState.SessionId(sessionId),
                CanonicalSessionState.SessionStatus.AVAILABLE, Optional.empty(), 0,
                Optional.empty(), List.of(), List.of());
        return new SessionDocument(CURRENT_SCHEMA_VERSION,
                new Metadata(sessionId, createdAt, Optional.empty()), 0, 1, List.of(), model,
                workingDirectory, Usage.ZERO, execution);
    }

    public SessionSnapshot snapshot() {
        List<Message> transcript = entries().stream()
                .filter(entry -> entry.kind() == EntryKind.MESSAGE)
                .map(Entry::message)
                .flatMap(Optional::stream)
                .toList();
        Optional<SessionSnapshot.ActiveRun> activeRun = execution.activeRun().map(run ->
                new SessionSnapshot.ActiveRun(run.id().value(), switch (run.status()) {
                    case RUNNING -> SessionSnapshot.Status.RUNNING;
                    case CANCELLING -> SessionSnapshot.Status.CANCELLING;
                    case PAUSED -> SessionSnapshot.Status.PAUSED;
                    case TERMINAL -> throw new IllegalStateException("terminal run cannot be active");
                }, run.revision()));
        return new SessionSnapshot(metadata.sessionId(), revision, model, workingDirectory, transcript, usage, activeRun);
    }

    /** Rebuilds model context from the latest compaction checkpoint without changing the full transcript. */
    public List<Message> providerContext() {
        List<Entry> branch = branch("main");
        int compactionIndex = -1;
        for (int index = branch.size() - 1; index >= 0; index--) {
            if (branch.get(index).kind() == EntryKind.COMPACTION) {
                compactionIndex = index;
                break;
            }
        }
        if (compactionIndex < 0) {
            return branch.stream().filter(entry -> entry.kind() == EntryKind.MESSAGE)
                    .map(Entry::message).flatMap(Optional::stream).toList();
        }
        Entry checkpoint = branch.get(compactionIndex);
        Object summaryValue = checkpoint.data().get("summary");
        Object retainedValue = checkpoint.data().get("retainedEntryIds");
        if (!(summaryValue instanceof String summary) || summary.isBlank()
                || !(retainedValue instanceof List<?> retainedValues)
                || retainedValues.stream().anyMatch(value -> !(value instanceof String))) {
            throw new IllegalStateException("compaction checkpoint data is invalid");
        }
        Map<String, Entry> byId = new LinkedHashMap<>();
        branch.forEach(entry -> byId.put(entry.id(), entry));
        var context = new ArrayList<Message>();
        context.add(new Message(checkpoint.id() + "-summary", Message.Role.USER,
                List.of(new io.github.diodeme.ji.ai.Content.Text(summary)), checkpoint.createdAt()));
        for (Object retainedId : retainedValues) {
            Entry retained = byId.get((String) retainedId);
            if (retained == null || retained.kind() != EntryKind.MESSAGE) {
                throw new IllegalStateException("compaction retained entry is missing");
            }
            context.add(retained.message().orElseThrow());
        }
        branch.subList(compactionIndex + 1, branch.size()).stream()
                .filter(entry -> entry.kind() == EntryKind.MESSAGE)
                .map(Entry::message).flatMap(Optional::stream).forEach(context::add);
        return List.copyOf(context);
    }

    public SessionDocument startRun(RunStart start) {
        Objects.requireNonNull(start, "start");
        if (execution.status() != CanonicalSessionState.SessionStatus.AVAILABLE) {
            throw new IllegalStateException("only an available Session may start a Run");
        }
        if (execution.activeRun().isPresent()) throw new IllegalStateException("Session already has an active Run");
        if (execution.compactions().stream().anyMatch(compaction ->
                compaction.status() != CanonicalSessionState.CompactionStatus.TERMINAL)) {
            throw new IllegalStateException("Session has an active Compaction");
        }
        var sessionId = execution.sessionId();
        var runId = new CanonicalSessionState.RunId(start.runId());
        var turnId = new CanonicalSessionState.TurnId(start.turnId());
        var attempt = new CanonicalSessionState.Attempt(
                new CanonicalSessionState.AttemptId(start.attemptId()), start.turnId(), 1,
                CanonicalSessionState.AttemptStep.ASSISTANT,
                CanonicalSessionState.AttemptStatus.RUNNING, Optional.empty(), 0,
                start.resultEntryId());
        var turn = new CanonicalSessionState.Turn(
                turnId, runId, 1, CanonicalSessionState.TurnStatus.MODEL_STREAMING,
                Optional.empty(), Optional.empty(), 0, List.of(attempt), List.of(), List.of());
        var run = new CanonicalSessionState.Run(
                runId, sessionId, CanonicalSessionState.RunStatus.RUNNING,
                Optional.empty(), Optional.empty(), 0, List.of(turn), start.startedAt(), Optional.empty());
        CanonicalSessionState nextExecution = new CanonicalSessionState(
                sessionId, execution.status(), execution.outcome(), Math.incrementExact(revision),
                Optional.of(run), execution.completedRuns(), execution.compactions());

        Projection projection = replay(log, nextSequence);
        Lane main = projection.lanes().stream().filter(lane -> lane.name().equals("main")).findFirst().orElseThrow();
        Entry entry = new Entry(start.prompt().id(), main.leafEntryId(), start.prompt().createdAt(),
                EntryKind.MESSAGE, Optional.of(start.prompt()), Map.of());
        List<Mutation> mutations = List.of(
                new EntryMutation(nextSequence, Optional.of("main"), entry),
                new RecordMutation(nextSequence + 1, new Record(
                        start.operationRecordId(), "main", RecordKind.OPERATION_STARTED,
                        Optional.of(start.runId()), Optional.of(OperationKind.RUN), Optional.empty(),
                        Map.of("turnId", start.turnId()), start.startedAt())),
                new RecordMutation(nextSequence + 2, new Record(
                        start.attemptRecordId(), "main", RecordKind.STEP_ATTEMPT,
                        Optional.of(start.runId()), Optional.of(OperationKind.RUN), Optional.empty(),
                        Map.of("turnId", start.turnId(), "attemptId", start.attemptId(), "attempt", 1),
                        start.startedAt())));
        return appendMutations(mutations, nextExecution, usage);
    }

    public SessionDocument pauseAfterRestart() {
        CanonicalSessionState paused = Recovery.pauseAfterRestart(execution);
        if (paused == execution) return this;
        return appendMutations(List.of(), paused, usage);
    }

    public SessionDocument startCompaction(CompactionStart start) {
        Objects.requireNonNull(start, "start");
        if (execution.status() != CanonicalSessionState.SessionStatus.AVAILABLE
                || execution.compactions().stream().anyMatch(compaction ->
                compaction.status() != CanonicalSessionState.CompactionStatus.TERMINAL)) {
            throw new IllegalStateException("Session cannot start compaction while an operation is active");
        }
        boolean manual = start.reason() == CompactionReason.MANUAL;
        if (manual != start.parentRunId().isEmpty()) {
            throw new IllegalArgumentException("manual compaction must not have a parent Run");
        }
        boolean activeParent = start.parentRunId().stream().anyMatch(parentRunId ->
                execution.activeRun().stream().anyMatch(run ->
                        run.id().value().equals(parentRunId)
                                && run.status() == CanonicalSessionState.RunStatus.RUNNING
                                && (run.turns().getLast().status() == CanonicalSessionState.TurnStatus.TERMINAL
                                || start.reason() == CompactionReason.OVERFLOW
                                && run.turns().getLast().status()
                                == CanonicalSessionState.TurnStatus.MODEL_STREAMING
                                && run.turns().getLast().attempts().getLast().status()
                                == CanonicalSessionState.AttemptStatus.RUNNING)));
        boolean completedParent = start.parentRunId().stream().anyMatch(parentRunId ->
                execution.completedRuns().stream().anyMatch(run -> run.id().value().equals(parentRunId)));
        if (!manual && !activeParent && !completedParent) {
            throw new IllegalStateException("automatic compaction parent Run is not at a safe boundary");
        }
        if (manual && execution.activeRun().isPresent()) {
            throw new IllegalStateException("manual compaction cannot start during a Run");
        }
        validateRetainedTail(start.retainedEntryIds());
        var attempt = new CanonicalSessionState.Attempt(
                new CanonicalSessionState.AttemptId(start.attemptId()), start.compactionId(), 1,
                CanonicalSessionState.AttemptStep.COMPACTION,
                CanonicalSessionState.AttemptStatus.RUNNING, Optional.empty(), 0,
                start.resultEntryId());
        var compaction = new CanonicalSessionState.Compaction(
                new CanonicalSessionState.CompactionId(start.compactionId()), execution.sessionId(),
                CanonicalSessionState.CompactionStatus.RUNNING, Optional.empty(), 0,
                List.of(attempt), Optional.empty());
        var compactions = new ArrayList<>(execution.compactions());
        compactions.add(compaction);
        Optional<CanonicalSessionState.Run> nextActiveRun = execution.activeRun();
        if (activeParent && start.reason() == CompactionReason.OVERFLOW
                && execution.activeRun().orElseThrow().turns().getLast().status()
                == CanonicalSessionState.TurnStatus.MODEL_STREAMING) {
            CanonicalSessionState.Run run = execution.activeRun().orElseThrow();
            CanonicalSessionState.Turn turn = run.turns().getLast();
            var attempts = new ArrayList<>(turn.attempts());
            CanonicalSessionState.Attempt providerAttempt = attempts.getLast();
            attempts.set(attempts.size() - 1, providerAttempt.finish(
                    CanonicalSessionState.AttemptOutcome.FAILED, providerAttempt.revision()));
            CanonicalSessionState.Turn waiting = turn.transition(
                    CanonicalSessionState.TurnStatus.WAITING_FOR_COMPACTION,
                    Optional.empty(), Optional.empty(), attempts, turn.tools(), turn.permissions(), turn.revision());
            var turns = new ArrayList<>(run.turns());
            turns.set(turns.size() - 1, waiting);
            nextActiveRun = Optional.of(new CanonicalSessionState.Run(
                    run.id(), run.sessionId(), run.status(), run.outcome(), run.pauseReason(),
                    Math.incrementExact(run.revision()), turns, run.startedAt(), run.endedAt()));
        }
        CanonicalSessionState nextExecution = new CanonicalSessionState(
                execution.sessionId(), execution.status(), execution.outcome(), Math.incrementExact(revision),
                nextActiveRun, execution.completedRuns(), compactions);
        Map<String, Object> input = new LinkedHashMap<>();
        input.put("compactionId", start.compactionId());
        input.put("attemptId", start.attemptId());
        input.put("attempt", 1);
        input.put("retainedEntryIds", start.retainedEntryIds());
        input.put("tokensBefore", start.tokensBefore());
        input.put("customInstructions", start.customInstructions());
        input.put("reason", start.reason().name().toLowerCase(java.util.Locale.ROOT));
        start.parentRunId().ifPresent(runId -> input.put("parentRunId", runId));
        boolean ownsOperation = manual || completedParent;
        String ownerId = ownsOperation ? start.compactionId() : start.parentRunId().orElseThrow();
        OperationKind ownerKind = ownsOperation ? OperationKind.COMPACTION : OperationKind.RUN;
        var mutations = new ArrayList<Mutation>();
        if (ownsOperation) {
            mutations.add(new RecordMutation(nextSequence, new Record(
                    start.operationRecordId(), "main", RecordKind.OPERATION_STARTED,
                    Optional.of(ownerId), Optional.of(ownerKind), Optional.empty(), input, start.startedAt())));
        }
        mutations.add(new RecordMutation(nextSequence + mutations.size(), new Record(
                start.attemptRecordId(), "main", RecordKind.STEP_ATTEMPT,
                Optional.of(ownerId), Optional.of(ownerKind), Optional.empty(), input, start.startedAt())));
        return appendMutations(mutations, nextExecution, usage);
    }

    public SessionDocument resumeCompaction(CompactionResume resume) {
        Objects.requireNonNull(resume, "resume");
        CanonicalSessionState resumed = Recovery.resumeCompaction(
                execution, new CanonicalSessionState.CompactionId(resume.compactionId()),
                new CanonicalSessionState.AttemptId(resume.attemptId()), resume.resultEntryId(),
                resume.compactionRevision());
        CanonicalSessionState.Compaction operation = resumed.compactions().stream()
                .filter(compaction -> compaction.id().value().equals(resume.compactionId()))
                .findFirst().orElseThrow();
        CompactionBinding binding = compactionBinding(resume.compactionId());
        Record attempt = new Record(
                resume.attemptRecordId(), "main", RecordKind.STEP_ATTEMPT,
                Optional.of(binding.operationId()), Optional.of(binding.operationKind()), Optional.empty(),
                Map.of("compactionId", resume.compactionId(), "attemptId", resume.attemptId(),
                        "attempt", operation.attempts().getLast().number(), "recovered", true),
                resume.resumedAt());
        return appendMutations(List.of(new RecordMutation(nextSequence, attempt)), resumed, usage);
    }

    public SessionDocument completeCompaction(CompactionCompletion completion) {
        Objects.requireNonNull(completion, "completion");
        int index = compactionIndex(completion.compactionId());
        CanonicalSessionState.Compaction compaction = execution.compactions().get(index);
        if (compaction.revision() != completion.compactionRevision()
                || compaction.status() != CanonicalSessionState.CompactionStatus.RUNNING) {
            throw new IllegalStateException("Compaction completion is stale");
        }
        CanonicalSessionState.Attempt attempt = compaction.attempts().getLast();
        if (!attempt.id().value().equals(completion.attemptId())
                || attempt.revision() != completion.attemptRevision()
                || !attempt.resultEntryId().equals(completion.resultEntryId())) {
            throw new IllegalStateException("Compaction completion belongs to another Attempt");
        }
        validateRetainedTail(completion.retainedEntryIds());
        var attempts = new ArrayList<>(compaction.attempts());
        attempts.set(attempts.size() - 1,
                attempt.finish(CanonicalSessionState.AttemptOutcome.SUCCEEDED, attempt.revision()));
        CanonicalSessionState.Compaction terminal = compaction.transition(
                CanonicalSessionState.CompactionStatus.TERMINAL,
                Optional.of(CanonicalSessionState.CompactionOutcome.COMPLETED), attempts,
                Optional.of(completion.resultEntryId()), compaction.revision());
        var compactions = new ArrayList<>(execution.compactions());
        compactions.set(index, terminal);
        CanonicalSessionState nextExecution = new CanonicalSessionState(
                execution.sessionId(), execution.status(), execution.outcome(), Math.incrementExact(revision),
                execution.activeRun(), execution.completedRuns(), compactions);

        Projection projection = replay(log, nextSequence);
        Optional<String> parent = projection.lanes().stream()
                .filter(lane -> lane.name().equals("main")).findFirst().orElseThrow().leafEntryId();
        Map<String, Object> data = new LinkedHashMap<>();
        data.put("summary", completion.summary());
        data.put("retainedEntryIds", completion.retainedEntryIds());
        data.put("tokensBefore", completion.tokensBefore());
        data.put("details", completion.details());
        Entry checkpoint = new Entry(
                completion.resultEntryId(), parent, completion.completedAt(), EntryKind.COMPACTION,
                Optional.empty(), data);
        CompactionBinding binding = compactionBinding(completion.compactionId());
        var mutations = new ArrayList<Mutation>();
        mutations.add(new EntryMutation(nextSequence, Optional.of("main"), checkpoint));
        mutations.add(new RecordMutation(nextSequence + 1, new Record(
                completion.usageRecordId(), "main", RecordKind.USAGE,
                Optional.of(binding.operationId()), Optional.of(binding.operationKind()), Optional.empty(),
                usageData(completion.usage()), completion.completedAt())));
        if (binding.ownsOperation()) {
            mutations.add(new RecordMutation(nextSequence + 2, new Record(
                    completion.operationRecordId(), "main", RecordKind.OPERATION_FINISHED,
                    Optional.of(binding.operationId()), Optional.of(binding.operationKind()),
                    Optional.of(OperationOutcome.COMPLETED), Map.of(), completion.completedAt())));
        }
        return appendMutations(mutations, nextExecution, usage.plus(completion.usage()));
    }

    public SessionDocument failCompaction(CompactionFailure failure) {
        Objects.requireNonNull(failure, "failure");
        int index = compactionIndex(failure.compactionId());
        CanonicalSessionState.Compaction compaction = execution.compactions().get(index);
        if (compaction.revision() != failure.compactionRevision()
                || compaction.status() != CanonicalSessionState.CompactionStatus.RUNNING) {
            throw new IllegalStateException("Compaction failure is stale");
        }
        CanonicalSessionState.Attempt attempt = compaction.attempts().getLast();
        if (!attempt.id().value().equals(failure.attemptId())
                || attempt.revision() != failure.attemptRevision()) {
            throw new IllegalStateException("Compaction failure belongs to another Attempt");
        }
        var attempts = new ArrayList<>(compaction.attempts());
        CanonicalSessionState.AttemptOutcome attemptOutcome = failure.outcome()
                == CanonicalSessionState.CompactionOutcome.CANCELLED
                ? CanonicalSessionState.AttemptOutcome.INTERRUPTED
                : CanonicalSessionState.AttemptOutcome.FAILED;
        attempts.set(attempts.size() - 1, attempt.finish(attemptOutcome, attempt.revision()));
        CanonicalSessionState.Compaction terminal = compaction.transition(
                CanonicalSessionState.CompactionStatus.TERMINAL, Optional.of(failure.outcome()), attempts,
                Optional.empty(), compaction.revision());
        var compactions = new ArrayList<>(execution.compactions());
        compactions.set(index, terminal);
        CanonicalSessionState nextExecution = new CanonicalSessionState(
                execution.sessionId(), execution.status(), execution.outcome(), Math.incrementExact(revision),
                execution.activeRun(), execution.completedRuns(), compactions);
        OperationOutcome outcome = failure.outcome() == CanonicalSessionState.CompactionOutcome.CANCELLED
                ? OperationOutcome.ABORTED : OperationOutcome.FAILED;
        CompactionBinding binding = compactionBinding(failure.compactionId());
        List<Mutation> mutations = binding.ownsOperation()
                ? List.of(new RecordMutation(nextSequence, new Record(
                        failure.operationRecordId(), "main", RecordKind.OPERATION_FINISHED,
                        Optional.of(binding.operationId()), Optional.of(binding.operationKind()), Optional.of(outcome),
                        Map.of("errorCode", failure.errorCode()), failure.completedAt())))
                : List.of();
        return appendMutations(mutations, nextExecution, usage);
    }

    public SessionDocument continueAfterOverflowCompaction(OverflowRetry retry) {
        Objects.requireNonNull(retry, "retry");
        CanonicalSessionState.Run run = requireActiveRun(retry.runId(), retry.runRevision());
        CanonicalSessionState.Turn turn = run.turns().getLast();
        if (!turn.id().value().equals(retry.turnId()) || turn.revision() != retry.turnRevision()
                || turn.status() != CanonicalSessionState.TurnStatus.WAITING_FOR_COMPACTION) {
            throw new IllegalStateException("overflow retry is stale or belongs to another Turn");
        }
        CanonicalSessionState.Compaction compaction = execution.compactions().stream()
                .filter(candidate -> candidate.id().value().equals(retry.compactionId()))
                .findFirst().orElseThrow(() -> new IllegalStateException("overflow Compaction does not exist"));
        if (compaction.status() != CanonicalSessionState.CompactionStatus.TERMINAL
                || compaction.outcome().orElse(null) != CanonicalSessionState.CompactionOutcome.COMPLETED) {
            throw new IllegalStateException("overflow Compaction has not completed");
        }
        Record start = records().stream()
                .filter(record -> record.data().get("compactionId") instanceof String value
                        && value.equals(retry.compactionId()))
                .findFirst().orElseThrow(() -> new IllegalStateException("overflow Compaction record is missing"));
        if (!retry.runId().equals(start.data().get("parentRunId"))
                || !"overflow".equals(start.data().get("reason"))) {
            throw new IllegalStateException("Compaction is not the overflow recovery for this Run");
        }
        var attempts = new ArrayList<>(turn.attempts());
        CanonicalSessionState.Attempt previous = attempts.getLast();
        attempts.add(new CanonicalSessionState.Attempt(
                new CanonicalSessionState.AttemptId(retry.attemptId()), turn.id().value(),
                previous.number() + 1, CanonicalSessionState.AttemptStep.ASSISTANT,
                CanonicalSessionState.AttemptStatus.RUNNING, Optional.empty(), 0, retry.resultEntryId()));
        CanonicalSessionState.Turn streaming = turn.transition(
                CanonicalSessionState.TurnStatus.MODEL_STREAMING,
                Optional.empty(), Optional.empty(), attempts, turn.tools(), turn.permissions(), turn.revision());
        CanonicalSessionState nextExecution = replaceActiveRunTurn(run, streaming);
        Record attempt = new Record(
                retry.attemptRecordId(), "main", RecordKind.STEP_ATTEMPT,
                Optional.of(run.id().value()), Optional.of(OperationKind.RUN), Optional.empty(),
                Map.of("turnId", turn.id().value(), "attemptId", retry.attemptId(),
                        "attempt", attempts.getLast().number(), "overflowRecovery", true), retry.startedAt());
        return appendMutations(List.of(new RecordMutation(nextSequence, attempt)), nextExecution, usage);
    }

