    public SessionDocument resumeToolBatch(List<ToolResumeStart> starts, Instant resumedAt) {
        Objects.requireNonNull(starts, "starts");
        Objects.requireNonNull(resumedAt, "resumedAt");
        CanonicalSessionState.Run run = execution.activeRun()
                .orElseThrow(() -> new IllegalStateException("no paused Run to resume"));
        CanonicalSessionState.Turn turn = run.turns().getLast();
        var startedTools = records().stream()
                .filter(record -> record.kind() == RecordKind.TOOL_STARTED)
                .map(record -> record.data().get("toolExecutionId"))
                .filter(String.class::isInstance).map(String.class::cast)
                .collect(java.util.stream.Collectors.toSet());
        List<Recovery.ToolResume> resumes = starts.stream().map(start -> new Recovery.ToolResume(
                new CanonicalSessionState.ToolExecutionId(start.executionId()),
                new CanonicalSessionState.AttemptId(start.attemptId()),
                startedTools.contains(start.executionId()))).toList();
        CanonicalSessionState resumed = Recovery.resumeTools(execution, resumes);
        CanonicalSessionState.Turn resumedTurn = resumed.activeRun().orElseThrow().turns().getLast();
        Map<String, CanonicalSessionState.ToolExecution> tools = resumedTurn.tools().stream().collect(
                java.util.stream.Collectors.toMap(tool -> tool.id().value(), tool -> tool));
        var mutations = new ArrayList<Mutation>();
        for (ToolResumeStart start : starts) {
            CanonicalSessionState.ToolExecution tool = tools.get(start.executionId());
            if (tool == null) throw new IllegalArgumentException("Tool recovery identity is not in the paused batch");
            CanonicalSessionState.Attempt attempt = tool.attempts().getLast();
            mutations.add(new RecordMutation(nextSequence + mutations.size(), new Record(
                    start.attemptRecordId(), "main", RecordKind.STEP_ATTEMPT,
                    Optional.of(run.id().value()), Optional.of(OperationKind.RUN), Optional.empty(),
                    Map.of("turnId", turn.id().value(), "toolExecutionId", tool.id().value(),
                            "attemptId", attempt.id().value(), "attempt", attempt.number(), "recovered", true),
                    resumedAt)));
        }
        return appendMutations(mutations, resumed, usage);
    }

    public SessionDocument finishRun(RunCompletion completion) {
        Objects.requireNonNull(completion, "completion");
        CanonicalSessionState.Run run = requireActiveRun(completion.runId(), completion.runRevision());
        CanonicalSessionState.Turn currentTurn = run.turns().getLast();
        if (!currentTurn.id().value().equals(completion.turnId())
                || currentTurn.revision() != completion.turnRevision()) {
            throw new IllegalStateException("Turn completion is stale or belongs to another Turn");
        }

        CanonicalSessionState.Turn terminalTurn = terminalTurn(currentTurn, completion);
        var turns = new ArrayList<>(run.turns());
        turns.set(turns.size() - 1, terminalTurn);
        CanonicalSessionState.Run terminalRun = new CanonicalSessionState.Run(
                run.id(), run.sessionId(), CanonicalSessionState.RunStatus.TERMINAL,
                Optional.of(completion.outcome()), Optional.empty(), Math.incrementExact(run.revision()),
                turns, run.startedAt(), Optional.of(completion.completedAt()));
        var completedRuns = new ArrayList<>(execution.completedRuns());
        completedRuns.add(terminalRun);
        CanonicalSessionState nextExecution = new CanonicalSessionState(
                execution.sessionId(), execution.status(), execution.outcome(), Math.incrementExact(revision),
                Optional.empty(), completedRuns, execution.compactions());

        var mutations = new ArrayList<Mutation>();
        appendMessageMutations(mutations, completion.messages());
        mutations.add(new RecordMutation(nextSequence + mutations.size(), new Record(
                completion.usageRecordId(), "main", RecordKind.USAGE,
                Optional.of(completion.runId()), Optional.of(OperationKind.RUN), Optional.empty(),
                usageData(completion.usage()), completion.completedAt())));
        mutations.add(new RecordMutation(nextSequence + mutations.size(), new Record(
                completion.operationRecordId(), "main", RecordKind.OPERATION_FINISHED,
                Optional.of(completion.runId()), Optional.of(OperationKind.RUN),
                Optional.of(operationOutcome(completion.outcome())),
                Map.of("turnId", completion.turnId()), completion.completedAt())));
        return appendMutations(mutations, nextExecution, usage.plus(completion.usage()));
    }

    public SessionDocument completeAssistantWithTools(AssistantCompletion completion) {
        Objects.requireNonNull(completion, "completion");
        if (completion.tools().isEmpty()) throw new IllegalArgumentException("Tool completion requires at least one Tool");
        CanonicalSessionState.Run run = requireActiveRun(completion.runId(), completion.runRevision());
        CanonicalSessionState.Turn turn = run.turns().getLast();
        if (!turn.id().value().equals(completion.turnId()) || turn.revision() != completion.turnRevision()
                || turn.status() != CanonicalSessionState.TurnStatus.MODEL_STREAMING) {
            throw new IllegalStateException("assistant completion is stale or belongs to another Turn");
        }
        var attempts = new ArrayList<>(turn.attempts());
        CanonicalSessionState.Attempt attempt = attempts.getLast();
        if (!attempt.id().value().equals(completion.attemptId())
                || attempt.revision() != completion.attemptRevision()) {
            throw new IllegalStateException("assistant completion is stale or belongs to another Attempt");
        }
        attempts.set(attempts.size() - 1,
                attempt.finish(CanonicalSessionState.AttemptOutcome.SUCCEEDED, attempt.revision()));

        var tools = new ArrayList<CanonicalSessionState.ToolExecution>();
        var permissions = new ArrayList<CanonicalSessionState.Permission>();
        for (ToolStart tool : completion.tools()) {
            var toolAttempt = new CanonicalSessionState.Attempt(
                    new CanonicalSessionState.AttemptId(tool.attemptId()), tool.executionId(), 1,
                    CanonicalSessionState.AttemptStep.TOOL,
                    CanonicalSessionState.AttemptStatus.RUNNING, Optional.empty(), 0, tool.resultEntryId());
            var execution = new CanonicalSessionState.ToolExecution(
                    new CanonicalSessionState.ToolExecutionId(tool.executionId()), this.execution.sessionId(),
                    run.id(), turn.id(), tool.toolCallId(), tool.toolName(), tool.resultEntryId(),
                    List.of(toolAttempt), tool.retryContract(), tool.resumeToken(),
                    CanonicalSessionState.ToolStatus.PREPARED, Optional.empty(), 0);
            tools.add(execution);
            tool.permission().ifPresent(permission -> permissions.add(new CanonicalSessionState.Permission(
                    new CanonicalSessionState.PermissionId(permission.permissionId()), this.execution.sessionId(),
                    execution.id(), CanonicalSessionState.PermissionStatus.PENDING, Optional.empty(), 0,
                    permission.expiresAt())));
        }
        CanonicalSessionState.Turn waiting = new CanonicalSessionState.Turn(
                turn.id(), turn.runId(), turn.number(), CanonicalSessionState.TurnStatus.WAITING_FOR_TOOLS,
                Optional.empty(), Optional.empty(), Math.incrementExact(turn.revision()),
                attempts, tools, permissions);
        CanonicalSessionState nextExecution = replaceActiveRunTurn(run, waiting);

        var mutations = new ArrayList<Mutation>();
        appendMessageMutations(mutations, completion.messages());
        mutations.add(new RecordMutation(nextSequence + mutations.size(), new Record(
                completion.usageRecordId(), "main", RecordKind.USAGE,
                Optional.of(completion.runId()), Optional.of(OperationKind.RUN), Optional.empty(),
                usageData(completion.usage()), completion.completedAt())));
        for (ToolStart tool : completion.tools()) {
            mutations.add(new RecordMutation(nextSequence + mutations.size(), new Record(
                    tool.recordId(), "main", RecordKind.TOOL_PREPARED,
                    Optional.of(completion.runId()), Optional.of(OperationKind.RUN), Optional.empty(),
                    Map.of("turnId", completion.turnId(), "toolExecutionId", tool.executionId(),
                            "toolCallId", tool.toolCallId(), "toolName", tool.toolName()),
                    completion.completedAt())));
        }
        return appendMutations(mutations, nextExecution, usage.plus(completion.usage()));
    }

    public SessionDocument resolveToolPermission(ToolPermissionResolution resolution) {
        Objects.requireNonNull(resolution, "resolution");
        CanonicalSessionState.Run run = requireActiveRun(resolution.runId(), resolution.runRevision());
        CanonicalSessionState.Turn turn = requireCurrentTurn(
                run, resolution.turnId(), resolution.turnRevision());
        if (run.status() != CanonicalSessionState.RunStatus.RUNNING
                || turn.status() != CanonicalSessionState.TurnStatus.WAITING_FOR_TOOLS) {
            throw new IllegalStateException("Permission resolution requires an active tool-waiting Turn");
        }
        int toolIndex = toolIndex(turn, resolution.executionId());
        CanonicalSessionState.ToolExecution tool = turn.tools().get(toolIndex);
        if (tool.revision() != resolution.toolRevision()
                || tool.status() != CanonicalSessionState.ToolStatus.PREPARED) {
            throw new IllegalStateException("Permission resolution is stale or belongs to another Tool");
        }
        var permissions = new ArrayList<>(turn.permissions());
        int permissionIndex = -1;
        for (int index = 0; index < permissions.size(); index++) {
            CanonicalSessionState.Permission candidate = permissions.get(index);
            if (candidate.id().value().equals(resolution.permissionId())) {
                permissionIndex = index;
                break;
            }
        }
        if (permissionIndex < 0) throw new IllegalStateException("Permission does not exist");
        CanonicalSessionState.Permission permission = permissions.get(permissionIndex);
        if (!permission.toolExecutionId().equals(tool.id())
                || permission.revision() != resolution.permissionRevision()) {
            throw new IllegalStateException("Permission resolution is stale or belongs to another Tool");
        }
        CanonicalSessionState.Permission resolved = permission.resolve(
                resolution.outcome(), permission.revision(), resolution.resolvedAt());
        permissions.set(permissionIndex, resolved);
        CanonicalSessionState.Turn nextTurn = new CanonicalSessionState.Turn(
                turn.id(), turn.runId(), turn.number(), turn.status(), turn.outcome(), turn.pausedFrom(),
                Math.incrementExact(turn.revision()), turn.attempts(), turn.tools(), permissions);
        CanonicalSessionState nextExecution = replaceActiveRunTurn(run, nextTurn);
        Record record = new Record(
                resolution.recordId(), "main", RecordKind.PERMISSION_RESOLVED,
                Optional.of(run.id().value()), Optional.of(OperationKind.RUN), Optional.empty(),
                Map.of("turnId", turn.id().value(), "toolExecutionId", tool.id().value(),
                        "permissionId", permission.id().value(), "outcome", resolved.outcome().orElseThrow().name()),
                resolution.resolvedAt());
        return appendMutations(List.of(new RecordMutation(nextSequence, record)), nextExecution, usage);
    }

    public SessionDocument startTool(ToolExecutionStart start) {
        Objects.requireNonNull(start, "start");
        CanonicalSessionState.Run run = requireActiveRun(start.runId(), start.runRevision());
        CanonicalSessionState.Turn turn = requireCurrentTurn(run, start.turnId(), start.turnRevision());
        if (run.status() != CanonicalSessionState.RunStatus.RUNNING
                || turn.status() != CanonicalSessionState.TurnStatus.WAITING_FOR_TOOLS) {
            throw new IllegalStateException("Tool start requires an active tool-waiting Turn");
        }
        int toolIndex = toolIndex(turn, start.executionId());
        CanonicalSessionState.ToolExecution tool = turn.tools().get(toolIndex);
        if (tool.revision() != start.toolRevision()
                || tool.status() != CanonicalSessionState.ToolStatus.PREPARED) {
            throw new IllegalStateException("Tool start is stale or belongs to another Tool");
        }
        CanonicalSessionState.Attempt attempt = tool.attempts().getLast();
        if (!attempt.id().value().equals(start.attemptId())
                || attempt.revision() != start.attemptRevision()
                || attempt.status() != CanonicalSessionState.AttemptStatus.RUNNING) {
            throw new IllegalStateException("Tool start is stale or belongs to another Attempt");
        }
        turn.permissions().stream()
                .filter(permission -> permission.toolExecutionId().equals(tool.id()))
                .forEach(permission -> {
                    if (permission.status() != CanonicalSessionState.PermissionStatus.RESOLVED
                            || permission.outcome().orElseThrow()
                            != CanonicalSessionState.PermissionOutcome.ALLOWED) {
                        throw new IllegalStateException("Tool cannot start without an allowed Permission");
                    }
                });
        var tools = new ArrayList<>(turn.tools());
        tools.set(toolIndex, tool.transition(
                CanonicalSessionState.ToolStatus.RUNNING, Optional.empty(), tool.attempts(), tool.revision()));
        CanonicalSessionState.Turn nextTurn = new CanonicalSessionState.Turn(
                turn.id(), turn.runId(), turn.number(), turn.status(), turn.outcome(), turn.pausedFrom(),
                Math.incrementExact(turn.revision()), turn.attempts(), tools, turn.permissions());
        CanonicalSessionState nextExecution = replaceActiveRunTurn(run, nextTurn);
        Record record = new Record(
                start.recordId(), "main", RecordKind.TOOL_STARTED,
                Optional.of(run.id().value()), Optional.of(OperationKind.RUN), Optional.empty(),
                Map.of("turnId", turn.id().value(), "toolExecutionId", tool.id().value(),
                        "attemptId", attempt.id().value()), start.startedAt());
        return appendMutations(List.of(new RecordMutation(nextSequence, record)), nextExecution, usage);
    }

