                turn.id(), turn.runId(), turn.number(), CanonicalSessionState.TurnStatus.TERMINAL,
                Optional.of(CanonicalSessionState.TurnOutcome.COMPLETED), Optional.empty(),
                Math.incrementExact(turn.revision()), attempts, turn.tools(), turn.permissions());
        var nextAttempt = new CanonicalSessionState.Attempt(
                new CanonicalSessionState.AttemptId(continuation.nextAttemptId()),
                continuation.nextTurnId(), 1, CanonicalSessionState.AttemptStep.ASSISTANT,
                CanonicalSessionState.AttemptStatus.RUNNING, Optional.empty(), 0,
                continuation.nextResultEntryId());
        var nextTurn = new CanonicalSessionState.Turn(
                new CanonicalSessionState.TurnId(continuation.nextTurnId()), run.id(),
                run.turns().size() + 1, CanonicalSessionState.TurnStatus.MODEL_STREAMING,
                Optional.empty(), Optional.empty(), 0, List.of(nextAttempt), List.of(), List.of());
        var turns = new ArrayList<>(run.turns());
        turns.set(turns.size() - 1, completedTurn);
        turns.add(nextTurn);
        var nextRun = new CanonicalSessionState.Run(
                run.id(), run.sessionId(), run.status(), run.outcome(), run.pauseReason(),
                Math.incrementExact(run.revision()), turns, run.startedAt(), run.endedAt());
        CanonicalSessionState nextExecution = new CanonicalSessionState(
                execution.sessionId(), execution.status(), execution.outcome(), Math.incrementExact(revision),
                Optional.of(nextRun), execution.completedRuns(), execution.compactions());

        var mutations = new ArrayList<Mutation>();
        var messages = new ArrayList<Message>(continuation.messages());
        messages.add(continuation.steer());
        appendMessageMutations(mutations, messages);
        mutations.add(new RecordMutation(nextSequence + mutations.size(), new Record(
                continuation.usageRecordId(), "main", RecordKind.USAGE,
                Optional.of(continuation.runId()), Optional.of(OperationKind.RUN), Optional.empty(),
                usageData(continuation.usage()), continuation.completedAt())));
        mutations.add(new RecordMutation(nextSequence + mutations.size(), new Record(
                continuation.nextAttemptRecordId(), "main", RecordKind.STEP_ATTEMPT,
                Optional.of(continuation.runId()), Optional.of(OperationKind.RUN), Optional.empty(),
                Map.of("turnId", continuation.nextTurnId(), "attemptId", continuation.nextAttemptId(),
                        "attempt", 1, "steerInjected", true), continuation.completedAt())));
        return appendMutations(mutations, nextExecution, usage.plus(continuation.usage()));
    }

    public SessionDocument completeToolBatch(ToolBatchCompletion completion) {
        Objects.requireNonNull(completion, "completion");
        CanonicalSessionState.Run run = requireActiveRun(completion.runId(), completion.runRevision());
        CanonicalSessionState.Turn turn = run.turns().getLast();
        if (!turn.id().value().equals(completion.turnId()) || turn.revision() != completion.turnRevision()
                || turn.status() != CanonicalSessionState.TurnStatus.WAITING_FOR_TOOLS) {
            throw new IllegalStateException("Tool completion is stale or belongs to another Turn");
        }
        Map<String, ToolResult> byId = completion.results().stream()
                .collect(java.util.stream.Collectors.toMap(ToolResult::executionId, value -> value));
        if (byId.size() != turn.tools().size()
                || turn.tools().stream().anyMatch(tool -> !byId.containsKey(tool.id().value()))) {
            throw new IllegalArgumentException("Tool completion must contain the complete prepared batch");
        }
        var tools = new ArrayList<CanonicalSessionState.ToolExecution>();
        for (CanonicalSessionState.ToolExecution tool : turn.tools()) {
            ToolResult result = byId.get(tool.id().value());
            if (tool.revision() != result.toolRevision()) throw new IllegalStateException("Tool completion revision is stale");
            CanonicalSessionState.Attempt attempt = tool.attempts().getLast();
            if (!attempt.id().value().equals(result.attemptId())
                    || attempt.revision() != result.attemptRevision()) {
                throw new IllegalStateException("Tool Attempt completion revision is stale");
            }
            CanonicalSessionState.AttemptOutcome attemptOutcome = result.outcome() == CanonicalSessionState.ToolOutcome.SUCCEEDED
                    ? CanonicalSessionState.AttemptOutcome.SUCCEEDED
                    : result.outcome() == CanonicalSessionState.ToolOutcome.CANCELLED
                    || result.outcome() == CanonicalSessionState.ToolOutcome.INTERRUPTED
                    ? CanonicalSessionState.AttemptOutcome.INTERRUPTED
                    : CanonicalSessionState.AttemptOutcome.FAILED;
            var attempts = new ArrayList<>(tool.attempts());
            attempts.set(attempts.size() - 1, attempt.finish(attemptOutcome, attempt.revision()));
            tools.add(new CanonicalSessionState.ToolExecution(
                    tool.id(), tool.sessionId(), tool.runId(), tool.turnId(), tool.toolCallId(), tool.toolName(),
                    tool.resultEntryId(), attempts, tool.retryContract(), tool.resumeToken(),
                    CanonicalSessionState.ToolStatus.TERMINAL, Optional.of(result.outcome()),
                    Math.incrementExact(tool.revision())));
        }
        var permissions = turn.permissions().stream().map(permission -> {
            ToolResult result = byId.get(permission.toolExecutionId().value());
            if (permission.status() == CanonicalSessionState.PermissionStatus.RESOLVED) return permission;
            CanonicalSessionState.PermissionOutcome outcome = result.permissionOutcome().orElse(
                    result.outcome() == CanonicalSessionState.ToolOutcome.SUCCEEDED
                            ? CanonicalSessionState.PermissionOutcome.ALLOWED
                            : CanonicalSessionState.PermissionOutcome.DENIED);
            return permission.resolve(outcome, permission.revision(), completion.completedAt());
        }).toList();
        boolean allSucceeded = tools.stream().allMatch(tool ->
                tool.outcome().orElseThrow() == CanonicalSessionState.ToolOutcome.SUCCEEDED);
        CanonicalSessionState.Turn terminal = new CanonicalSessionState.Turn(
                turn.id(), turn.runId(), turn.number(), CanonicalSessionState.TurnStatus.TERMINAL,
                Optional.of(allSucceeded ? CanonicalSessionState.TurnOutcome.COMPLETED
                        : CanonicalSessionState.TurnOutcome.FAILED),
                Optional.empty(), Math.incrementExact(turn.revision()), turn.attempts(), tools, permissions);
        CanonicalSessionState nextExecution = replaceActiveRunTurn(run, terminal);
        var mutations = new ArrayList<Mutation>();
        appendMessageMutations(mutations, completion.results().stream().map(ToolResult::message).toList());
        return appendMutations(mutations, nextExecution, usage);
    }

    public SessionDocument beginNextTurn(TurnStart start) {
        Objects.requireNonNull(start, "start");
        CanonicalSessionState.Run run = requireActiveRun(start.runId(), start.runRevision());
        if (!run.turns().isEmpty() && run.turns().getLast().status() != CanonicalSessionState.TurnStatus.TERMINAL) {
            throw new IllegalStateException("a new Turn requires the prior Turn to be terminal");
        }
        var turnId = new CanonicalSessionState.TurnId(start.turnId());
        var attempt = new CanonicalSessionState.Attempt(
                new CanonicalSessionState.AttemptId(start.attemptId()), start.turnId(), 1,
                CanonicalSessionState.AttemptStep.ASSISTANT,
                CanonicalSessionState.AttemptStatus.RUNNING, Optional.empty(), 0, start.resultEntryId());
        var turn = new CanonicalSessionState.Turn(
                turnId, run.id(), run.turns().size() + 1,
                CanonicalSessionState.TurnStatus.MODEL_STREAMING,
                Optional.empty(), Optional.empty(), 0, List.of(attempt), List.of(), List.of());
        var turns = new ArrayList<>(run.turns());
        turns.add(turn);
        var nextRun = new CanonicalSessionState.Run(
                run.id(), run.sessionId(), run.status(), run.outcome(), run.pauseReason(),
                Math.incrementExact(run.revision()), turns, run.startedAt(), run.endedAt());
        CanonicalSessionState nextExecution = new CanonicalSessionState(
                execution.sessionId(), execution.status(), execution.outcome(), Math.incrementExact(revision),
                Optional.of(nextRun), execution.completedRuns(), execution.compactions());
        var mutations = new ArrayList<Mutation>();
        start.injectedSteer().ifPresent(message -> appendMessageMutations(mutations, List.of(message)));
        mutations.add(new RecordMutation(nextSequence + mutations.size(), new Record(
                start.attemptRecordId(), "main", RecordKind.STEP_ATTEMPT,
                Optional.of(start.runId()), Optional.of(OperationKind.RUN), Optional.empty(),
                Map.of("turnId", start.turnId(), "attemptId", start.attemptId(), "attempt", 1,
                        "steerInjected", start.injectedSteer().isPresent()), start.startedAt())));
        return appendMutations(mutations, nextExecution, usage);
    }

    public SessionDocument requestAbort(String runId, long expectedRunRevision) {
        CanonicalSessionState.Run run = requireActiveRun(runId, expectedRunRevision);
        CanonicalSessionState.Run cancelling = run.transition(
                CanonicalSessionState.RunStatus.CANCELLING, Optional.empty(), Optional.empty(),
                Optional.empty(), expectedRunRevision);
        CanonicalSessionState nextExecution = new CanonicalSessionState(
                execution.sessionId(), execution.status(), execution.outcome(), Math.incrementExact(revision),
                Optional.of(cancelling), execution.completedRuns(), execution.compactions());
        return appendMutations(List.of(), nextExecution, usage);
    }

    /** Restores the semantic state that existed before a Run whose terminal CAS did not commit. */
    public SessionDocument rollbackRun(String runId, SessionDocument baseline) {
        requireText(runId, "runId");
        Objects.requireNonNull(baseline, "baseline");
        CanonicalSessionState.Run run = execution.activeRun()
                .orElseThrow(() -> new IllegalStateException("Session has no active Run to roll back"));
        if (!run.id().value().equals(runId)) {
            throw new IllegalStateException("Run rollback belongs to another Run");
        }
        if (!metadata.sessionId().equals(baseline.metadata.sessionId())
                || baseline.revision() >= revision
                || baseline.execution().activeRun().isPresent()) {
            throw new IllegalArgumentException("Run rollback baseline is not a prior available Session revision");
        }
        long nextRevision = Math.incrementExact(revision);
        CanonicalSessionState restored = baseline.execution();
        CanonicalSessionState nextExecution = new CanonicalSessionState(
                restored.sessionId(), restored.status(), restored.outcome(), nextRevision,
                restored.activeRun(), restored.completedRuns(), restored.compactions());
        return new SessionDocument(
                baseline.schemaVersion(), baseline.metadata(), nextRevision, baseline.nextSequence(),
                baseline.log(), baseline.model(), baseline.workingDirectory(), baseline.usage(), nextExecution);
    }

    private CanonicalSessionState replaceActiveRunTurn(
            CanonicalSessionState.Run run, CanonicalSessionState.Turn replacement) {
        var turns = new ArrayList<>(run.turns());
        turns.set(turns.size() - 1, replacement);
        var nextRun = new CanonicalSessionState.Run(
                run.id(), run.sessionId(), run.status(), run.outcome(), run.pauseReason(),
                Math.incrementExact(run.revision()), turns, run.startedAt(), run.endedAt());
        return new CanonicalSessionState(
                execution.sessionId(), execution.status(), execution.outcome(), Math.incrementExact(revision),
                Optional.of(nextRun), execution.completedRuns(), execution.compactions());
    }

    private static CanonicalSessionState.Turn requireCurrentTurn(
            CanonicalSessionState.Run run, String turnId, long expectedRevision) {
        CanonicalSessionState.Turn turn = run.turns().getLast();
        if (!turn.id().value().equals(turnId) || turn.revision() != expectedRevision
                || turn.status() != CanonicalSessionState.TurnStatus.WAITING_FOR_TOOLS) {
            throw new IllegalStateException("Tool transition is stale or belongs to another Turn");
        }
        return turn;
    }

    private static int toolIndex(CanonicalSessionState.Turn turn, String executionId) {
        for (int index = 0; index < turn.tools().size(); index++) {
            if (turn.tools().get(index).id().value().equals(executionId)) return index;
        }
        throw new IllegalStateException("Tool execution does not exist");
    }

    private int compactionIndex(String compactionId) {
        for (int index = 0; index < execution.compactions().size(); index++) {
            if (execution.compactions().get(index).id().value().equals(compactionId)) return index;
        }
        throw new IllegalStateException("Compaction does not exist");
    }

    private CompactionBinding compactionBinding(String compactionId) {
        Record start = records().stream()
                .filter(record -> record.data().get("compactionId") instanceof String value
                        && value.equals(compactionId))
                .findFirst().orElseThrow(() -> new IllegalStateException("Compaction start record does not exist"));
        boolean ownsOperation = start.operationKind().orElseThrow() == OperationKind.COMPACTION;
        return new CompactionBinding(
                start.operationId().orElseThrow(), start.operationKind().orElseThrow(), ownsOperation);
    }

    private void validateRetainedTail(List<String> retainedEntryIds) {
        List<String> messageIds = branch("main").stream()
                .filter(entry -> entry.kind() == EntryKind.MESSAGE).map(Entry::id).toList();
        if (retainedEntryIds.size() > messageIds.size()
                || !messageIds.subList(messageIds.size() - retainedEntryIds.size(), messageIds.size())
                .equals(retainedEntryIds)) {
            throw new IllegalArgumentException("compaction retained entries must be a contiguous message suffix");
        }
    }

    private CanonicalSessionState.Turn terminalTurn(
            CanonicalSessionState.Turn turn, RunCompletion completion) {
        var attempts = new ArrayList<>(turn.attempts());
        for (int index = 0; index < attempts.size(); index++) {
            CanonicalSessionState.Attempt attempt = attempts.get(index);
            if (attempt.id().value().equals(completion.attemptId())) {
                if (attempt.revision() != completion.attemptRevision()) {
                    throw new IllegalStateException("Attempt completion revision is stale");
                }
                if (attempt.status() != CanonicalSessionState.AttemptStatus.TERMINAL) {
                    attempts.set(index, attempt.finish(attemptOutcome(completion.outcome()), attempt.revision()));
                }
            }
        }
        if (attempts.stream().noneMatch(attempt -> attempt.id().value().equals(completion.attemptId()))) {
            throw new IllegalStateException("Attempt completion belongs to another Attempt");
        }

        var tools = turn.tools().stream().map(tool -> terminalTool(tool, completion.outcome())).toList();
        var permissions = turn.permissions().stream().map(permission ->
                permission.status() == CanonicalSessionState.PermissionStatus.RESOLVED ? permission
                        : new CanonicalSessionState.Permission(
                                permission.id(), permission.sessionId(), permission.toolExecutionId(),
                                CanonicalSessionState.PermissionStatus.RESOLVED,
                                Optional.of(CanonicalSessionState.PermissionOutcome.DENIED),
                                Math.incrementExact(permission.revision()), permission.expiresAt())).toList();
        return new CanonicalSessionState.Turn(
                turn.id(), turn.runId(), turn.number(), CanonicalSessionState.TurnStatus.TERMINAL,
                Optional.of(turnOutcome(completion.outcome())), Optional.empty(),
                Math.incrementExact(turn.revision()), attempts, tools, permissions);
    }

    private static CanonicalSessionState.ToolExecution terminalTool(
            CanonicalSessionState.ToolExecution tool, CanonicalSessionState.RunOutcome outcome) {
        if (tool.status() == CanonicalSessionState.ToolStatus.TERMINAL) return tool;
        var attempts = new ArrayList<>(tool.attempts());
        CanonicalSessionState.Attempt attempt = attempts.getLast();
        if (attempt.status() != CanonicalSessionState.AttemptStatus.TERMINAL) {
            CanonicalSessionState.AttemptOutcome attemptOutcome = outcome == CanonicalSessionState.RunOutcome.FAILED
                    ? CanonicalSessionState.AttemptOutcome.FAILED
                    : CanonicalSessionState.AttemptOutcome.INTERRUPTED;
            attempts.set(attempts.size() - 1, attempt.finish(attemptOutcome, attempt.revision()));
        }
        CanonicalSessionState.ToolOutcome toolOutcome = switch (outcome) {
            case DECLINED -> CanonicalSessionState.ToolOutcome.DENIED;
            case ABORTED -> CanonicalSessionState.ToolOutcome.CANCELLED;
            case FAILED -> CanonicalSessionState.ToolOutcome.FAILED;
            case COMPLETED -> CanonicalSessionState.ToolOutcome.SUCCEEDED;
        };
        return new CanonicalSessionState.ToolExecution(
                tool.id(), tool.sessionId(), tool.runId(), tool.turnId(), tool.toolCallId(), tool.toolName(),
                tool.resultEntryId(), attempts, tool.retryContract(), tool.resumeToken(),
                CanonicalSessionState.ToolStatus.TERMINAL, Optional.of(toolOutcome),
                Math.incrementExact(tool.revision()));
    }

    private void appendMessageMutations(List<Mutation> mutations, List<Message> messages) {
        Optional<String> parent = replay(log, nextSequence).lanes().stream()
                .filter(lane -> lane.name().equals("main")).findFirst().orElseThrow().leafEntryId();
        for (Message message : messages) {
            Entry entry = new Entry(message.id(), parent, message.createdAt(), EntryKind.MESSAGE,
                    Optional.of(message), Map.of());
            mutations.add(new EntryMutation(nextSequence + mutations.size(), Optional.of("main"), entry));
            parent = Optional.of(message.id());
        }
    }

    private CanonicalSessionState.Run requireActiveRun(String runId, long expectedRevision) {
        CanonicalSessionState.Run run = execution.activeRun()
                .orElseThrow(() -> new IllegalStateException("Session has no active Run"));
        if (!run.id().value().equals(runId) || run.revision() != expectedRevision) {
            throw new IllegalStateException("Run completion is stale or belongs to another Run");
        }
        return run;
    }

    private static CanonicalSessionState.AttemptOutcome attemptOutcome(CanonicalSessionState.RunOutcome outcome) {
        return switch (outcome) {
            case COMPLETED -> CanonicalSessionState.AttemptOutcome.SUCCEEDED;
            case FAILED -> CanonicalSessionState.AttemptOutcome.FAILED;
            case ABORTED, DECLINED -> CanonicalSessionState.AttemptOutcome.INTERRUPTED;
        };
    }

    private static CanonicalSessionState.TurnOutcome turnOutcome(CanonicalSessionState.RunOutcome outcome) {
        return switch (outcome) {
            case COMPLETED -> CanonicalSessionState.TurnOutcome.COMPLETED;
            case FAILED, DECLINED -> CanonicalSessionState.TurnOutcome.FAILED;
            case ABORTED -> CanonicalSessionState.TurnOutcome.ABORTED;
        };
    }

    private static OperationOutcome operationOutcome(CanonicalSessionState.RunOutcome outcome) {
        return switch (outcome) {
            case COMPLETED -> OperationOutcome.COMPLETED;
            case ABORTED -> OperationOutcome.ABORTED;
            case FAILED -> OperationOutcome.FAILED;
            case DECLINED -> OperationOutcome.DECLINED;
        };
    }

    private static Map<String, Object> usageData(Usage value) {
        return Map.of(
                "inputTokens", value.inputTokens(),
                "outputTokens", value.outputTokens(),
                "cacheReadTokens", value.cacheReadTokens(),
                "cacheWriteTokens", value.cacheWriteTokens(),
                "costMicros", value.costMicros());
    }

