    public List<Entry> branch(String laneName) {
        Projection state = replay(log, nextSequence);
        String leaf = state.lanes().stream().filter(lane -> lane.name().equals(laneName)).findFirst()
                .orElseThrow(() -> new IllegalArgumentException("lane not found: " + laneName))
                .leafEntryId().orElse(null);
        Map<String, Entry> byId = new HashMap<>();
        state.entries().forEach(entry -> byId.put(entry.id(), entry));
        var reversed = new ArrayList<Entry>();
        var visited = new HashSet<String>();
        while (leaf != null) {
            if (!visited.add(leaf)) throw new IllegalStateException("Session branch contains a cycle at " + leaf);
            Entry current = byId.get(leaf);
            if (current == null) throw new IllegalStateException("Session branch references missing entry " + leaf);
            reversed.add(current);
            leaf = current.parentId().orElse(null);
        }
        return reversed.reversed();
    }

    public SessionDocument appendEntry(String lane, String id, EntryKind kind, Optional<Message> message,
                                       Map<String, Object> data, Instant createdAt) {
        Projection state = replay(log, nextSequence);
        Lane pointer = state.lanes().stream().filter(candidate -> candidate.name().equals(lane)).findFirst()
                .orElseThrow(() -> new IllegalArgumentException("lane not found: " + lane));
        Entry entry = new Entry(id, pointer.leafEntryId(), createdAt, kind, message, data);
        return appendMutation(new EntryMutation(nextSequence, Optional.of(lane), entry));
    }

