    public SessionDocument fork(String sessionId, String laneName, Optional<String> targetEntryId,
                                ForkPosition position, Instant createdAt) {
        requireText(sessionId, "sessionId");
        Objects.requireNonNull(targetEntryId, "targetEntryId");
        Objects.requireNonNull(position, "position");
        List<Entry> sourceBranch = branch(laneName);
        String selected = targetEntryId.orElseGet(() -> sourceBranch.isEmpty() ? null : sourceBranch.getLast().id());
        List<Entry> copied;
        if (selected == null) {
            copied = List.of();
        } else {
            Entry target = entry(selected).orElseThrow(() -> new IllegalArgumentException("fork target not found: " + selected));
            if (target.kind() != EntryKind.MESSAGE) throw new IllegalArgumentException("fork target must be a message entry");
            if (sourceBranch.stream().noneMatch(candidate -> candidate.id().equals(selected))) {
                throw new IllegalArgumentException("fork target is not on the selected lane");
            }
            String lastIncluded = position == ForkPosition.AT ? target.id() : target.parentId().orElse(null);
            var mutable = new ArrayList<Entry>();
            for (Entry entry : sourceBranch) {
                if (lastIncluded == null) break;
                mutable.add(entry);
                if (entry.id().equals(lastIncluded)) break;
            }
            copied = List.copyOf(mutable);
        }
        long sequence = 1;
        var forkLog = new ArrayList<Mutation>();
        for (Entry entry : copied) {
            forkLog.add(new EntryMutation(sequence++, Optional.of("main"), entry));
        }
        if (name().isPresent()) forkLog.add(new NameFactMutation(sequence++, name()));
        Map<String, String> labels = labels();
        for (Entry entry : copied) {
            String label = labels.get(entry.id());
            if (label != null) forkLog.add(new LabelFactMutation(sequence++, entry.id(), Optional.of(label)));
        }
        return new SessionDocument(CURRENT_SCHEMA_VERSION,
                new Metadata(sessionId, createdAt, Optional.of(metadata.sessionId())), 0, sequence,
                forkLog, model, workingDirectory, Usage.ZERO,
                new CanonicalSessionState(new CanonicalSessionState.SessionId(sessionId),
                        CanonicalSessionState.SessionStatus.AVAILABLE, Optional.empty(), 0,
                        Optional.empty(), List.of(), List.of()));
    }

    private SessionDocument appendMutation(Mutation mutation) {
        return appendMutations(List.of(mutation), incrementExecution(execution), usage);
    }

    private SessionDocument appendMutations(
            List<? extends Mutation> mutations, CanonicalSessionState nextExecution, Usage nextUsage) {
        long nextRevision = Math.incrementExact(revision);
        if (nextExecution.revision() != nextRevision) {
            throw new IllegalStateException("execution transition must advance the document revision once");
        }
        var nextLog = new ArrayList<>(log);
        nextLog.addAll(mutations);
        return new SessionDocument(schemaVersion, metadata, nextRevision,
                Math.addExact(nextSequence, mutations.size()), nextLog, model, workingDirectory,
                nextUsage, nextExecution);
    }

    public enum ForkPosition { BEFORE, AT }
    public enum EntryKind { MESSAGE, MODEL_CHANGE, THINKING_LEVEL_CHANGE, ACTIVE_TOOLS_CHANGE, COMPACTION, BRANCH_SUMMARY, CUSTOM }
    public enum RecordKind { OPERATION_STARTED, OPERATION_FINISHED, STEP_ATTEMPT, TOOL_PREPARED, TOOL_STARTED, PERMISSION_RESOLVED, QUEUE_ENQUEUED, QUEUE_CANCELLED, USAGE }
    public enum OperationKind { RUN, COMPACTION, NAVIGATION }
    public enum OperationOutcome { COMPLETED, ABORTED, FAILED, DECLINED }
    public enum LaneMutationKind { CREATE, MOVE }

    public record RunStart(
            String runId,
            String turnId,
            String attemptId,
            String resultEntryId,
            Message prompt,
            String operationRecordId,
            String attemptRecordId,
            Instant startedAt) {
        public RunStart {
            requireText(runId, "runId");
            requireText(turnId, "turnId");
            requireText(attemptId, "attemptId");
            requireText(resultEntryId, "resultEntryId");
            Objects.requireNonNull(prompt, "prompt");
            if (prompt.role() != Message.Role.USER) throw new IllegalArgumentException("Run prompt must be a user message");
            requireText(operationRecordId, "operationRecordId");
            requireText(attemptRecordId, "attemptRecordId");
            Objects.requireNonNull(startedAt, "startedAt");
        }
    }

    public record CompactionStart(
            String compactionId,
            String attemptId,
            String resultEntryId,
            List<String> retainedEntryIds,
            long tokensBefore,
            String customInstructions,
            CompactionReason reason,
            Optional<String> parentRunId,
            String operationRecordId,
            String attemptRecordId,
            Instant startedAt) {
        public CompactionStart {
            requireText(compactionId, "compactionId");
            requireText(attemptId, "attemptId");
            requireText(resultEntryId, "resultEntryId");
            retainedEntryIds = List.copyOf(retainedEntryIds);
            retainedEntryIds.forEach(value -> requireText(value, "retainedEntryId"));
            if (tokensBefore < 0) throw new IllegalArgumentException("tokensBefore must be non-negative");
            customInstructions = customInstructions == null ? "" : customInstructions;
            Objects.requireNonNull(reason, "reason");
            parentRunId = parentRunId == null ? Optional.empty() : parentRunId;
            parentRunId.ifPresent(value -> requireText(value, "parentRunId"));
            requireText(operationRecordId, "operationRecordId");
            requireText(attemptRecordId, "attemptRecordId");
            Objects.requireNonNull(startedAt, "startedAt");
        }
    }

    public enum CompactionReason { MANUAL, THRESHOLD, OVERFLOW }

    private record CompactionBinding(String operationId, OperationKind operationKind, boolean ownsOperation) {}

